      process.querySelectorAll('.process-sheet g[data-step]').forEach(function(g){
        sheetGroups[g.getAttribute('data-step')] = g;
      });
    }
  }
}
measureAct();
addEventListener('resize', measureAct, { passive:true });
addEventListener('load', measureAct);

/* PLAN 019, R6, device-tabellens rad 9. --sc-ps som DRIVER ritningen
   kommer från motorn (#process har data-sc-act="flow"); den här läsaren
   räknar en EGEN, billig approximation ur rå scrollY (F-013, ingen
   getComputedStyle per bildruta). */
function processPs(){
  var travel = processH + window.innerHeight;
  if (travel <= 0) return 0;
  var ps = (window.scrollY + window.innerHeight - processTop) / travel;
  if (ps < 0) ps = 0; else if (ps > 1) ps = 1;
  return ps;
}

var turning = null, pending = false;
var groupsOn = {};
function readState(){
  pending = false;
  var travel = Math.max(actH - window.innerHeight, 1);
  var ps = (window.scrollY - actTop) / travel;
  if (ps < 0) ps = 0; else if (ps > 1) ps = 1;
  var moving = ps > 0.0005 && ps < 0.9995;
  if (moving !== turning){
    turning = moving;
    hero.classList.toggle('is-turning', moving);
  }
  /* smoothstep(0.10, 0.78, ps) korsar 0,5 exakt vid ps = 0,44. */
  if (previewFace !== null) { setFace(previewFace); } else { setFace(ps >= 0.44); }

  /* PLAN 031. Latch: --rv = max(tidigare, smoothstep(from, to, ps)) ur
     shimens lerpade cur (ingen stilläsning). Skrivs bara när värdet ökar,
     så efter revealen sker noll skrivningar och den kan aldrig backa. */
  for (var r = 0; r < reveals.length; r++){
    var R = reveals[r];
    /* AVVIKELSE: R.act löst en gång vid mount-tid (direkt efter
       ScrollCraft.mount) hann före sc-smooth.js:s egen collect(), som
       väntar på DOMContentLoaded om dokumentet fortfarande parsas -
       window.__scSmooth.acts var då fortfarande tom och --rv stod fast
       vid 0 för alltid (uppmätt). Löses lazy här i stället, försöker
       igen varje readState-anrop tills den hittar sin akt. */
    if (!R.act) R.act = (window.__scSmooth && window.__scSmooth.acts || []).filter(function(a){ return a.el.matches(R.sel); })[0] || null;
    var act = R.act;
    var cur = act && !isNaN(act.cur) ? act.cur : 0;
    var t = Math.min(1, Math.max(0, (cur - R.from) / (R.to - R.from)));
    t = t * t * (3 - 2 * t);
    if (t > R.v + 0.002){ R.v = t; R.el.style.setProperty('--rv', t.toFixed(4)); }
  }

  if (process){
    var pps = processPs();
    /* PLAN 019 Step 6, device-tabellens rad 8 (perf 3): en grupp vars
       fönster ännu inte öppnat ligger utanför stilträdet (display:none
       via frånvaro av data-on). AVVIKELSE från planens sheetGroups[i]-
       indexering: g[data-step="05"] måste ligga FÖRST i DOM för
       paint-ordning (Calyx-bilden under #p-opening:s kontur), så
       positionen i sheetGroups matchar inte stepAnchors[i]:s ordning.
       En nyckeluppslagning per data-step-värde är robust oavsett
       DOM-ordning; steg 06 har ingen egen grupp (inga nya banor det
       steget, bara tonövergångar på redan ritade element via --k6) och
       hoppas över. */
    for (var i = 0; i < stepAnchors.length; i++){
      var stepNum = (i + 1 < 10 ? '0' : '') + (i + 1);
      var g = sheetGroups[stepNum];
      if (!g) continue;
      /* PLAN 025 B4 (Astra loop 1, fix 2): rå pps (osmoothad) slog av
         gruppen så fort den korsade s, medan --sc-ps (lerpad) fortfarande
         låg kvar över s och banan fortfarande höll på att dra sig
         tillbaka visuellt - ett klipp i stället för en baklängesritning.
         0,03 av life ≈ 135px vid 1440, mer än lerpen hinner släpa. */
      var on = groupsOn[stepNum] ? pps >= stepAnchors[i].s - 0.03 : pps >= stepAnchors[i].s;
      if (groupsOn[stepNum] !== on){
        groupsOn[stepNum] = on;
        g.toggleAttribute('data-on', on);
      }
    }
  }
}
