"""035 step 3+4: after landing, 0 --rv writes on further scroll + latchRaf null;
scroll back up from price to thesis with wheel keeps --rv at 1 (never reverses)."""
import asyncio, sys
from playwright.async_api import async_playwright
CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe"
URL = "http://localhost:3301/tests/alunix-r8/runs/V3c/index.html"

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CHROME)
        page = await b.new_page(viewport={"width":1440,"height":900}, device_scale_factor=1, reduced_motion="reduce")
        await page.goto(URL, wait_until="load", timeout=60000)
        await page.wait_for_timeout(1000)
        # scroll to band, wheel, let it land
        for _ in range(48):
            await page.mouse.wheel(0, 100)
            await page.wait_for_timeout(60)
        await page.wait_for_timeout(2500)
        rv_before = await page.evaluate("[document.querySelector('.calyx-wrap').style.getPropertyValue('--rv'), document.querySelector('.horai-wrap').style.getPropertyValue('--rv')]")
        # install a write counter
        await page.evaluate("""() => {
          window.__rvWrites = 0;
          const wraps = [document.querySelector('.calyx-wrap'), document.querySelector('.horai-wrap')];
          for (const w of wraps) {
            const orig = w.style.setProperty.bind(w.style);
            w.style.setProperty = function(name, val, prio) {
              if (name === '--rv') window.__rvWrites++;
              return orig(name, val, prio);
            };
          }
        }""")
        # scroll further down 3000px
        await page.mouse.wheel(0, 3000)
        await page.wait_for_timeout(1500)
        writes = await page.evaluate("window.__rvWrites")
        latch_raf = await page.evaluate("window.latchRaf === undefined ? 'no-global' : window.latchRaf")
        rv_after = await page.evaluate("[document.querySelector('.calyx-wrap').style.getPropertyValue('--rv'), document.querySelector('.horai-wrap').style.getPropertyValue('--rv')]")
        print("step3:", {"rv_before": rv_before, "writes_after_landing": writes, "rv_after": rv_after})

        # step 4: scroll back up to thesis with wheel, check --rv stays 1
        for _ in range(60):
            await page.mouse.wheel(0, -150)
            await page.wait_for_timeout(30)
        await page.wait_for_timeout(1000)
        rv_up = await page.evaluate("[document.querySelector('.calyx-wrap').style.getPropertyValue('--rv'), document.querySelector('.horai-wrap').style.getPropertyValue('--rv')]")
        print("step4_scroll_up_rv:", rv_up)
        await b.close()

asyncio.run(main())

