"""036 step 3: pixel check. Force --rv 0.25/0.5/0.75/1 on both wrappers with
frames mounted+awake, screenshot each wrapper, compare against shots/r8/*12-1440-*.png."""
import asyncio
from playwright.async_api import async_playwright
CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe"
URL = "http://localhost:3301/tests/alunix-r8/runs/V3c/index.html"
OUT = "C:/Users/Anton L/anti-slop-design/tests/alunix-r8/runs/V3c/shots/r9/p036"

async def main():
    import os
    os.makedirs(OUT, exist_ok=True)
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CHROME)
        page = await b.new_page(viewport={"width":1440,"height":900}, device_scale_factor=1, reduced_motion="reduce")
        await page.goto(URL, wait_until="load", timeout=60000)
        await page.wait_for_timeout(600)
        # mount both frames and hold them awake
        await page.evaluate("""() => {
          document.querySelectorAll('iframe[data-src]').forEach(f=>{ if(!f.src){ f.src=f.getAttribute('data-src'); f.removeAttribute('data-src'); }});
          document.querySelectorAll('.frame-wrap').forEach(w=>w.classList.remove('is-asleep'));
        }""")
