"""036 B verification: (1) frames stay unmounted while idle at top (no perpetual
rAF drain), (2) frames mount once heron's --sc-ps >= 0.80 even far from the band,
(3) is-asleep still applies outside the 40% zone despite pre-mounting."""
import asyncio
from playwright.async_api import async_playwright
CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe"
URL = "http://localhost:3301/tests/alunix-r8/runs/V3c/index.html"

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CHROME)
        page = await b.new_page(viewport={"width":1440,"height":900}, device_scale_factor=1, reduced_motion="reduce")
        await page.goto(URL, wait_until="load", timeout=60000)
        await page.wait_for_timeout(1500)  # let everything settle at scrollY 0

        # (1) idle at top: rAF should have stopped, iframes must still be unmounted
        rafcount = await page.evaluate("""() => new Promise(res => {
          let n = 0;
          function count(){ n++; if (n < 30) requestAnimationFrame(count); else res(n); }
          requestAnimationFrame(count);
        })""")
        srcs = await page.evaluate("Array.from(document.querySelectorAll('iframe')).map(f => !!f.getAttribute('src'))")
        print("idle_at_top: mounted_srcs =", srcs, "(expect [false, false])")

        # scroll to just past hero's own act (hero span 3.4 * vh roughly; walk down slowly and watch heroAct.cur)
        for _ in range(60):
            await page.mouse.wheel(0, 80)
            await page.wait_for_timeout(30)
            st = await page.evaluate("""() => {
              const acts = (window.__scSmooth && window.__scSmooth.acts) || [];
              const hero = document.getElementById('hero-section');
              const a = acts.filter(x => x.el === hero)[0];
              return a ? a.cur : null;
            }""")
            if st is not None and st >= 0.80:
                break
        await page.wait_for_timeout(1000)
        y = await page.evaluate("window.scrollY")
        srcs2 = await page.evaluate("Array.from(document.querySelectorAll('iframe')).map(f => ({src: !!f.getAttribute('src'), asleep: f.closest('.frame-wrap').classList.contains('is-asleep')}))")
        print("after_hero_tail: scrollY =", y, "hero_cur =", st, "frames =", srcs2)
        await b.close()

asyncio.run(main())

