"""Compare the ENGINE's own cached act.top/act.height for #process against
the PAGE's own processTop/processH at the same moment, to find the geometry
mismatch behind ps != e in frozen preview mode."""
import asyncio
from playwright.async_api import async_playwright
CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe"
URL = "http://localhost:3301/tests/alunix-r8/runs/V3c/index.html?preview=process-01"

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=CHROME)
        page = await b.new_page(viewport={"width":1440,"height":900}, device_scale_factor=1, reduced_motion="reduce")
        await page.goto(URL, wait_until="load", timeout=60000)
        await page.wait_for_timeout(1500)
        st = await page.evaluate("""() => {
          const inst = window.ScrollCraft && window.ScrollCraft.instances && window.ScrollCraft.instances[0];
          const p = document.getElementById('process');
          let engineAct = null;
          if (inst) engineAct = inst.acts.filter(a => a.el === p)[0];
          const rect = p.getBoundingClientRect();
          return {
            engine: engineAct ? {top: engineAct.top, height: engineAct.height, raw: engineAct.raw, p: engineAct.p} : null,
            scrollY: scrollY,
            rectTopNow: rect.top,
            rectTopPlusScroll: rect.top + scrollY,
            docScrollHeight: document.documentElement.scrollHeight,
            vh: innerHeight
          };
        }""")
        print(st)
        await b.close()

asyncio.run(main())

