        await page.goto(URL, wait_until="load", timeout=60000)
        await page.wait_for_timeout(1500)
        st = await page.evaluate("""() => {
          const inst = window.ScrollCraft && window.ScrollCraft.instances && window.ScrollCraft.instances[0];
