          const stick = p.querySelector('.process-stick');
          const stickRect = stick ? stick.getBoundingClientRect() : null;
          const lis = document.querySelectorAll('.process-steps li');
          const li2 = lis[1] ? lis[1].getBoundingClientRect() : null;
          return {
            engineTop: engineAct ? engineAct.top : null,
            engineHeight: engineAct ? engineAct.height : null,
            engineRaw: engineAct ? engineAct.raw : null,
            rectTopPlusScroll: rect.top + scrollY,
            rectHeight: rect.height,
